kind: Service
metadata: {name: kube-state-metrics, namespace: monitoring}
spec:
  selector: {app.kubernetes.io/name: kube-state-metrics}
  ports: [{name: http, port: 8080, targetPort: http}]
---
apiVersion: apps/v1
kind: Deployment
metadata: {name: kube-state-metrics, namespace: monitoring}
spec:
  replicas: 1
  selector: {matchLabels: {app.kubernetes.io/name: kube-state-metrics}}
  template:
    metadata: {labels: {app.kubernetes.io/name: kube-state-metrics}}
    spec:
      serviceAccountName: kube-state-metrics
      enableServiceLinks: false
      nodeSelector: {pg-ha/role: infra}
      tolerations: [{key: node-role.kubernetes.io/control-plane, operator: Exists, effect: NoSchedule}]
      securityContext:
        runAsNonRoot: true
        runAsUser: 65534
        runAsGroup: 65534
        seccompProfile: {type: RuntimeDefault}
      containers:
        - name: kube-state-metrics
          image: __KUBE_STATE_METRICS_IMAGE__
          imagePullPolicy: IfNotPresent
          args:
            - --resources=cronjobs,jobs,statefulsets,deployments
            - --namespaces=pg-ha,kube-system
            - --port=8080
            - --telemetry-port=8081
          ports:
            - {name: http, containerPort: 8080}
            - {name: telemetry, containerPort: 8081}
          readinessProbe: {httpGet: {path: /readyz, port: telemetry}, periodSeconds: 5}
          livenessProbe: {httpGet: {path: /livez, port: http}, periodSeconds: 15, failureThreshold: 6}
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities: {drop: [ALL]}
          resources:
            requests: {cpu: 10m, memory: 32Mi}
            limits: {memory: 128Mi}

